315	/** duplicate_count → 각성 단계 계산 (모든 등급 최대 ★5) */
316	export function getAwakeningLevel(grade: string, duplicateCount: number): number {
317	  if (grade === 'R') {
318	    if (duplicateCount >= 100) return 5;
319	    if (duplicateCount >= 75)  return 4;
320	    if (duplicateCount >= 50)  return 3;
321	    if (duplicateCount >= 25)  return 2;
322	    if (duplicateCount >= 10)  return 1;
323	  } else if (grade === 'SR') {
324	    if (duplicateCount >= 40) return 5;
325	    if (duplicateCount >= 25) return 4;
326	    if (duplicateCount >= 15) return 3;
327	    if (duplicateCount >= 7)  return 2;
328	    if (duplicateCount >= 3)  return 1;
329	  } else if (grade === 'UR') {
330	    if (duplicateCount >= 10) return 5;
331	    if (duplicateCount >= 6)  return 4;
332	    if (duplicateCount >= 4)  return 3;
333	    if (duplicateCount >= 2)  return 2;
334	    if (duplicateCount >= 1)  return 1;
335	  }
336	  return 0;
337	}
338	
339	const DUPES_KEY     = 'duplicateCounts';
340	const DUPES_SIG_KEY = 'duplicateCountsSig';
341	const _DUPES_SALT   = 'ddong-dupes-\u0076\u0032';
342	
343	/** djb2 해시 — key:value 쌍을 정렬 후 직렬화해 서명 */
344	function _signDupes(map: Record<string, number>): string {
345	  const str = Object.entries(map)
346	    .sort(([a], [b]) => a.localeCompare(b))
347	    .map(([k, v]) => `${k}:${v}`)
348	    .join(',') + _DUPES_SALT;
349	  let h = 5381;
350	  for (let i = 0; i < str.length; i++) h = (((h << 5) + h) ^ str.charCodeAt(i)) >>> 0;
351	  return h.toString(36);
352	}
353	
354	function _saveDupes(map: Record<string, number>): void {
355	  localStorage.setItem(DUPES_KEY, JSON.stringify(map));
356	  localStorage.setItem(DUPES_SIG_KEY, _signDupes(map));
357	}
358	
359	/** 캐릭터별 중복 획득 횟수 반환. 서명 불일치 시 변조로 판단해 전체 초기화. */
360	export function getDuplicateCount(id: string): number {
361	  try {
362	    const raw = localStorage.getItem(DUPES_KEY);
363	    const sig = localStorage.getItem(DUPES_SIG_KEY);
364	    const map: Record<string, number> = raw ? JSON.parse(raw) : {};
365	
366	    if (sig === null) {
367	      // 서명 미존재 → 기존 데이터 마이그레이션: 신뢰하고 서명 최초 발급
368	      _saveDupes(map);
369	      return map[id] ?? 0;
370	    }
371	
372	    // 서명 불일치 → 변조로 판단, 전체 초기화
373	    if (sig !== _signDupes(map)) {
374	      _saveDupes({});
375	      return 0;
376	    }
377	
378	    return map[id] ?? 0;
379	  } catch {
380	    return 0;
381	  }
382	}
383	
384	/** 캐릭터별 중복 획득 횟수 저장 (뽑기 완료 후 호출) */
385	export function setDuplicateCount(id: string, count: number): void {
386	  try {
387	    const raw = localStorage.getItem(DUPES_KEY);
388	    const sig = localStorage.getItem(DUPES_SIG_KEY);
389	    const map: Record<string, number> = raw ? JSON.parse(raw) : {};
390	
391	    // 변조된 상태에서 쓰기 시도 → 기존 맵 무시하고 새로 시작
392	    if (sig !== null && sig !== _signDupes(map)) {
393	      _saveDupes({ [id]: count });
394	      return;
395	    }
396	
397	    map[id] = count;
398	    _saveDupes(map);
399	  } catch { /* ignore */ }
400	}
401	
402	const OWNED_KEY = 'ownedCharacters';
403	const OWNED_SIG_KEY = 'ownedCharactersSig';
404	const SELECTED_KEY = 'selectedCharacter';
405	const _SIG_SALT = 'ddong-v2-\u0073\u006b\u006f\u0072';
406	
407	/** djb2 해시 → base36 문자열 (무결성 서명용) */
408	function _sign(list: string[]): string {
409	  const str = [...list].sort().join(',') + _SIG_SALT;
410	  let h = 5381;
411	  for (let i = 0; i < str.length; i++) h = (((h << 5) + h) ^ str.charCodeAt(i)) >>> 0;
412	  return h.toString(36);
413	}
414	
415	/** 보유 목록과 서명을 함께 저장 (내부 전용) */
416	function _saveOwned(list: string[]): void {
417	  localStorage.setItem(OWNED_KEY, JSON.stringify(list));
418	  localStorage.setItem(OWNED_SIG_KEY, _sign(list));
419	}
420	
421	/** 보유 캐릭터 목록 반환. 서명 불일치 시 변조로 판단하여 초기화. */
422	export function getOwnedCharacters(): string[] {
423	  try {
424	    const raw = localStorage.getItem(OWNED_KEY);
425	    const sig = localStorage.getItem(OWNED_SIG_KEY);
426	    const list: string[] = raw ? JSON.parse(raw) : [];
427	    if (!list.includes('chibi')) list.unshift('chibi');
428	
429	    if (sig === null) {
430	      // 서명 미존재 → 기존 데이터 마이그레이션: 목록을 신뢰하고 서명 최초 발급
431	      _saveOwned(list);
432	      return list;
433	    }
434	
435	    // 서명 존재하지만 불일치 → 변조로 판단, chibi만 남김
436	    if (sig !== _sign(list)) {
437	      _saveOwned(['chibi']);
438	      return ['chibi'];
439	    }
440	
441	    return list;
442	  } catch {
443	    return ['chibi'];
444	  }
445	}
446	
447	/** 서버 동기화 등 외부에서 목록 전체를 덮어쓸 때 사용 (서명 함께 갱신) */
448	export function setOwnedCharacters(list: string[]): void {
449	  if (!list.includes('chibi')) list.unshift('chibi');
450	  _saveOwned(list);
451	}
452	
453	/** 캐릭터를 보유 목록에 추가 (뽑기 완료 후 호출) */
454	export function addOwnedCharacter(id: string): void {
455	  const owned = getOwnedCharacters();
456	  if (!owned.includes(id)) {
457	    owned.push(id);
458	    _saveOwned(owned);
459	  }
460	}
461	
462	/** 선택된 캐릭터 ID 반환. 없으면 'chibi'. */
463	export function getSelectedCharacter(): string {
464	  return localStorage.getItem(SELECTED_KEY) ?? 'chibi';
465	}
466	
467	/** 선택된 캐릭터 저장 */
468	export function setSelectedCharacter(id: string): void {
469	  localStorage.setItem(SELECTED_KEY, id);
470	}
471	
472	/** 소유 목록과 교차 검증하여 안전한 캐릭터 ID 반환. 미보유면 'chibi'로 강제 초기화. */
473	export function getSafeSelectedCharacter(): string {
474	  const selected = getSelectedCharacter();
475	  const owned = getOwnedCharacters();
476	  if (owned.includes(selected)) return selected;
477	  // 변조 감지 → chibi로 강제 초기화
478	  setSelectedCharacter('chibi');
479	  return 'chibi';
480	}
481	
482	/** 캐릭터 정의 조회 */
483	export function getCharacterDef(id: string): CharacterDef {
484	  return CHARACTERS.find(c => c.id === id) ?? CHARACTERS[0];
485	}
