import Phaser from 'phaser';
import { BaseAbility } from './BaseAbility';
import type { GameSceneAPI, SpecialPoopType } from './types';
import { MUGI_PARAMS } from '../config/abilityParams';

const HARVEST_REPEAT = Math.floor(MUGI_PARAMS.harvestDuration / MUGI_PARAMS.harvestSpawnMs) - 1;

export class MugiAbility extends BaseAbility {
  private _api: GameSceneAPI | null = null;
  private harvestTimer: Phaser.Time.TimerEvent | null = null;
  private flashTween: Phaser.Tweens.Tween | null = null;

  onCreate(api: GameSceneAPI): void {
    this._api = api;
  }

  onScoreMilestone(score: number, api: GameSceneAPI): void {
    if (score % MUGI_PARAMS.harvestInterval === 0 && this.harvestTimer === null) {
      this._startHarvest(api);
    }
  }

  private _startHarvest(api: GameSceneAPI): void {
    const scene = api.scene;
    const flash = scene.add.graphics();
    flash.fillStyle(0xffcc00, 0.35);
    flash.fillCircle(api.player.x, api.player.y, 60);
    flash.setDepth(200);
    this.flashTween = scene.tweens.add({
      targets: flash,
      alpha: 0,
      scaleX: 2.5,
      scaleY: 2.5,
      duration: 600,
      ease: 'Quad.easeOut',
      onComplete: () => {
        flash.destroy();
        this.flashTween = null;
      },
    });

    this.harvestTimer = scene.time.addEvent({
      delay: MUGI_PARAMS.harvestSpawnMs,
      repeat: HARVEST_REPEAT,
      callback: () => {
        for (let i = 0; i < MUGI_PARAMS.harvestSpawnCount; i++) {
          api.spawnGoldPoop();
        }
        if (this.harvestTimer?.repeatCount === 0) {
          this.harvestTimer = null;
        }
      },
    });
  }

  onCollectSpecial(type: SpecialPoopType): number {
    if (this._api) {
      switch (type) {
        case 'gold':    this._api.spawnGoldPoop();    break;
        case 'diamond': this._api.spawnDiamondPoop(); break;
        case 'topaz':   this._api.spawnTopazPoop();   break;
        case 'rainbow': this._api.spawnRainbowPoop(); break;
      }
    }
    return 0;
  }

  onDestroy(_api: GameSceneAPI): void {
    this.harvestTimer?.remove();
    this.harvestTimer = null;
    this.flashTween?.stop();
    this.flashTween = null;
    this._api = null;
  }
}

